<?php
/**
 * @var string $transaction_time
 * @var int|string $sale_id
 * @var string $invoice_number
 * @var string $employee
 * @var array $cart
 * @var float $discount
 * @var float $prediscount_subtotal
 * @var float $subtotal
 * @var array $taxes
 * @var float $total
 * @var array $payments
 * @var float $amount_change
 * @var string $barcode
 * @var array $config
 */

$company_name = !empty($config['company']) ? $config['company'] : 'GRAFF';
if (stripos($company_name, 'Open Source') !== false) {
    $company_name = 'GRAFF KIDS';
}

$phone_display = !empty($config['phone']) && $config['phone'] !== '555-555-5555' ? $config['phone'] : '+91 91881 15555';

$outlet_name = '';
if (!empty($config['address']) && stripos($config['address'], 'Nowhere') === false) {
    $lines = explode("\n", str_replace("\r", "", $config['address']));
    $outlet_name = trim($lines[0]);
}
if (empty($outlet_name)) {
    $outlet_name = 'Graff Coimbatore';
}

$formatted_sale_id = str_starts_with((string)$sale_id, 'POS') ? $sale_id : 'POS ' . $sale_id;
?>

<div id="receipt_wrapper" style="font-family: Arial, sans-serif !important; font-size: 11px !important; max-width: 300px; margin: 0 auto; padding: 14px 12px; background: #fff; box-shadow: 0 1px 6px rgba(0,0,0,0.15); color: #111;">
    <div id="receipt_header" style="text-align: center;">

        <div id="company_name" style="text-align:center; margin-bottom: 3px;">
        <img src="data:image/png;base64," style="max-height: 95px; max-width: 240px;" alt="Graff Kids">
    </div>
    <div style="text-align:center; font-size: 16px; font-weight: bold; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 2px; color: #111;">GRAFF KIDS</div>

        <div id="company_phone" style="font-size: 10.5px; color: #222; margin-bottom: 6px;">
            <?= esc($phone_display) ?>
        </div>

        <div id="sale_receipt" style="font-size: 12px; font-weight: bold; margin-top: 4px; margin-bottom: 2px;">
            <?= lang('Sales.receipt') ?>
        </div>

        <div id="sale_time" style="font-size: 10px; color: #333; margin-bottom: 10px;">
            <?= esc($transaction_time) ?>
        </div>
    </div>

    <div id="receipt_general_info" style="font-size: 10px; line-height: 1.4; margin-bottom: 10px; text-align: left;">
        <?php if (isset($customer)) { ?>
            <div id="customer"><?= lang('Customers.customer') . esc(": $customer") ?></div>
        <?php } ?>

        <div id="sale_id"><?= 'Sale ID: ' . esc($formatted_sale_id) ?></div>

        <?php if (!empty($invoice_number)) { ?>
            <div id="invoice_number"><?= lang('Sales.invoice_number') . esc(": $invoice_number") ?></div>
        <?php } ?>

        <div id="outlet">Outlet: <?= esc($outlet_name) ?></div>

        <?php if (!empty($employee)) { ?>
            <div id="employee"><?= lang('Employees.employee') . esc(": $employee") ?></div>
        <?php } ?>
    </div>

    <table id="receipt_items" style="width: 100%; border-collapse: collapse; margin-top: 2px; font-size: 10px;">
        <tr>
            <th style="width: 42%; font-weight: bold; padding: 3px 0 4px 0; border-bottom: 1px solid #111; text-align: left;"><?= lang('Sales.description_abbrv') ?></th>
            <th style="width: 21%; font-weight: bold; padding: 3px 0 4px 0; border-bottom: 1px solid #111; text-align: left;"><?= lang('Sales.price') ?></th>
            <th style="width: 16%; font-weight: bold; padding: 3px 0 4px 0; border-bottom: 1px solid #111; text-align: center;"><?= lang('Sales.quantity') ?></th>
            <th style="width: 21%; font-weight: bold; padding: 3px 0 4px 0; border-bottom: 1px solid #111; text-align: right;"><?= lang('Sales.total') ?></th>
        </tr>
        <?php
        foreach ($cart as $line => $item) {
            if ($item['print_option'] == PRINT_YES) {
        ?>
                <tr>
                    <td style="text-align: left; padding: 3px 0; vertical-align: top;">
                        <div><?= esc(ucfirst($item['name'] . ' ' . $item['attribute_values'])) ?></div>
                        <?php if (false && !empty(trim($item['description'] ?? ''))) { ?>
                            <div style="font-size: 80%; color: #555; font-style: italic;"><?= esc($item['description']) ?></div>
                        <?php } ?>
                        <?php if ($config['receipt_show_serialnumber'] && !empty(trim($item['serialnumber'] ?? ''))) { ?>
                            <div style="font-size: 80%; color: #666;"><?= esc($item['serialnumber']) ?></div>
                        <?php } ?>
                    </td>
                    <td style="text-align: left; padding: 3px 0; vertical-align: top;"><?= to_currency($item['price']) ?></td>
                    <td style="text-align: center; padding: 3px 0; vertical-align: top;"><?= to_quantity_decimals($item['quantity']) ?></td>
                    <td style="text-align: right; padding: 3px 0; vertical-align: top;"><?= to_currency($item[($config['receipt_show_total_discount'] ? 'total' : 'discounted_total')]) ?></td>
                </tr>
                <?php if ($item['discount'] > 0) { ?>
                    <tr>
                        <?php if ($item['discount_type'] == FIXED) { ?>
                            <td colspan="3" class="discount" style="font-size: 85%; color: #666;"><?= to_currency($item['discount']) . " " . lang('Sales.discount') ?></td>
                        <?php } elseif ($item['discount_type'] == PERCENT) { ?>
                            <td colspan="3" class="discount" style="font-size: 85%; color: #666;"><?= to_decimals($item['discount']) . " " . lang('Sales.discount_included') ?></td>
                        <?php } ?>
                        <td style="text-align: right;"><?= to_currency($item['discounted_total']) ?></td>
                    </tr>
                <?php } ?>
        <?php
            }
        }
        ?>
    </table>

    <div style="border-top: 1.2px solid #111; margin: 6px 0 6px 0;"></div>

    <table id="receipt_totals" style="width: 100%; border-collapse: collapse; font-size: 10px;">
        <?php if ($config['receipt_show_total_discount'] && $discount > 0) { ?>
            <tr>
                <td style="text-align: right; font-size: 9.5px; color: #555; padding: 1px 0;"><?= lang('Sales.sub_total') ?>:</td>
                <td style="text-align: right; width: 40%; font-size: 9.5px; color: #555; padding: 1px 0;"><?= to_currency($prediscount_subtotal) ?></td>
            </tr>
            <tr>
                <td style="text-align: right; font-size: 9.5px; color: #555; padding: 1px 0;"><?= lang('Sales.customer_discount') ?>:</td>
                <td style="text-align: right; width: 40%; font-size: 9.5px; color: #555; padding: 1px 0;"><?= to_currency($discount * -1) ?></td>
            </tr>
        <?php } ?>

        <?php if ($config['receipt_show_taxes']) { ?>
            <?php foreach ($taxes as $tax_group_index => $tax) { ?>
                <tr>
                    <td style="text-align: right; font-size: 9.5px; color: #555; padding: 1px 0;"><?= (float)$tax['tax_rate'] . '% ' . esc($tax['tax_group']) ?>:</td>
                    <td style="text-align: right; width: 40%; font-size: 9.5px; color: #555; padding: 1px 0;"><?= to_currency_tax($tax['sale_tax_amount']) ?></td>
                </tr>
            <?php } ?>
        <?php } ?>

        <tr style="font-weight: bold; font-size: 11px;">
            <td style="text-align: right; padding: 3px 0;"><?= lang('Sales.total') ?></td>
            <td style="text-align: right; width: 40%; padding: 3px 0;"><?= to_currency($total) ?></td>
        </tr>

        <tr><td colspan="2" style="height: 4px;"></td></tr>

        <?php
        $only_sale_check = false;
        $show_giftcard_remainder = false;
        foreach ($payments as $payment_id => $payment) {
            $only_sale_check |= $payment['payment_type'] == lang('Sales.check');
            $splitpayment = explode(':', $payment['payment_type']);
            $show_giftcard_remainder |= $splitpayment[0] == lang('Sales.giftcard');
        ?>
            <tr>
                <td style="text-align: right; padding: 2px 0;"><?= esc($splitpayment[0]) ?></td>
                <td style="text-align: right; width: 40%; padding: 2px 0;"><?= to_currency(abs($payment['payment_amount'])) ?></td>
            </tr>
        <?php } ?>

        <?php if (isset($cur_giftcard_value) && $show_giftcard_remainder) { ?>
            <tr>
                <td style="text-align: right; padding: 2px 0;"><?= lang('Sales.giftcard_balance') ?></td>
                <td style="text-align: right; width: 40%; padding: 2px 0;"><?= to_currency($cur_giftcard_value) ?></td>
            </tr>
        <?php } ?>
        <tr>
            <td style="text-align: right; padding: 2px 0;"><?= lang($amount_change >= 0 ? ($only_sale_check ? 'Sales.check_balance' : 'Sales.change_due') : 'Sales.amount_due') ?></td>
            <td style="text-align: right; width: 40%; padding: 2px 0;"><?= to_currency(abs($amount_change)) ?></td>
        </tr>
    </table>

    <?php if (!empty($config['return_policy']) && trim($config['return_policy']) !== 'Test') { ?>
        <div id="sale_return_policy" style="text-align: center; font-size: 8.5px; color: #555; margin-top: 8px;">
            <?= nl2br(esc($config['return_policy'])) ?>
        </div>
    <?php } ?>

    <div id="barcode" style="text-align: center; margin-top: 14px;">
        <?= $barcode ?><br>
        <div style="font-size: 10px; font-weight: bold; letter-spacing: 1.5px; margin-top: 3px;"><?= esc($formatted_sale_id) ?></div>
    </div>

    <div style="text-align: center; margin-top: 15px; margin-bottom: 5px;">
        <img src="<?= base_url('images/ganesha_emblem.png') ?>" alt="Seal" style="width: 72px; height: 72px; display: inline-block;" />
    </div>
</div>